const topics: ExpansionTopic[] = [
  { id: 'mt-good-devs-say-no', slugPt: 'por-que-bons-desenvolvedores-dizem-nao', slugEn: 'why-good-developers-say-no', title: { pt: 'Por Que Bons Desenvolvedores Dizem Não Com Frequência', en: 'Why Good Developers Say No Often' }, excerpt: { pt: 'Saber recusar soluções ruins, prazos impossíveis e decisões técnicas fracas faz parte da maturidade de qualquer desenvolvedor.', en: 'Knowing how to refuse weak solutions, impossible deadlines and poor technical decisions is part of developer maturity.' }, readTime: '14 min', tags: { pt: ['Carreira', 'Decisões', 'Profissionalismo'], en: ['Career', 'Decisions', 'Professionalism'] }, keywords: { pt: ['dizer não como desenvolvedor', 'decisão técnica', 'maturidade profissional'], en: ['saying no as a developer', 'technical decision', 'professional maturity'] }, subject: 'recusar decisões ruins', angle: 'Dizer não não é falta de colaboração. Em muitos casos é exatamente o contrário. É assumir responsabilidade antes que uma escolha mal pensada vire problema para usuário, equipe e negócio.', work: 'Isso aparece quando alguém pede uma entrega sem escopo, uma integração sem segurança ou uma gambiarra que parece economizar tempo no início.', mistake: 'aceitar tudo para parecer fácil de trabalhar', practice: 'Comece explicando o risco com calma, ofereça uma alternativa viável e registre a decisão quando ela afetar prazo, segurança ou manutenção.', bridge: 'No próximo artigo, a mesma ideia aparece no estudo. Nem todo esforço é progresso, e estudar errado também custa caro.' },
  { id: 'mt-studying-wrong-way', slugPt: 'como-saber-se-voce-esta-estudando-errado', slugEn: 'how-to-know-you-are-studying-wrong', title: { pt: 'Como Saber Se Você Está Estudando do Jeito Errado', en: 'How to Know If You Are Studying the Wrong Way' }, excerpt: { pt: 'Nem toda rotina de estudo gera evolução. Aprenda a perceber quando você está ocupado, mas não está ficando melhor.', en: 'Not every study routine creates progress. Learn how to notice when you are busy but not improving.' }, readTime: '13 min', tags: { pt: ['Estudo', 'Aprendizado', 'Evolução'], en: ['Study', 'Learning', 'Growth'] }, keywords: { pt: ['estudar programação', 'rotina de estudos', 'aprender melhor'], en: ['studying programming', 'study routine', 'learning better'] }, subject: 'estudo com resultado', angle: 'O estudo errado costuma dar sensação de movimento. Você assiste aulas, salva links, abre várias abas e termina o dia cansado. O problema é que cansaço não prova aprendizado.', work: 'Isso aparece quando a pessoa sabe repetir o que viu em aula, mas trava quando precisa resolver um problema um pouco diferente.', mistake: 'medir evolução pela quantidade de conteúdo consumido', practice: 'Depois de cada conteúdo, crie algo pequeno sem olhar a resposta. Se travar, volte ao conceito específico que falhou, não ao curso inteiro.', bridge: 'Quando o estudo começa a gerar prática real, o próximo obstáculo é lidar com os momentos em que o código simplesmente não anda.' },
  { id: 'mt-stuck-in-code', slugPt: 'o-que-fazer-quando-voce-trava-no-codigo', slugEn: 'what-to-do-when-you-get-stuck-in-code', title: { pt: 'O Que Fazer Quando Você Trava em Um Problema de Código', en: 'What to Do When You Get Stuck in a Code Problem' }, excerpt: { pt: 'Travar faz parte da profissão. A diferença está em como você investiga o problema sem depender sempre de alguém salvando você.', en: 'Getting stuck is part of the job. The difference is how you investigate the problem without always depending on someone else.' }, readTime: '14 min', tags: { pt: ['Debug', 'Autonomia', 'Problemas'], en: ['Debug', 'Autonomy', 'Problems'] }, keywords: { pt: ['travado no código', 'debug', 'resolver problema de programação'], en: ['stuck in code', 'debugging', 'solving programming problems'] }, subject: 'investigar problemas', angle: 'Travar não significa que você não serve para programar. Significa que encontrou uma parte do problema que ainda não sabe decompor.', work: 'No trabalho, isso acontece em bug de produção, integração quebrada, erro intermitente ou comportamento que ninguém consegue reproduzir de primeira.', mistake: 'pedir resposta antes de entender onde o problema começa', practice: 'Reduza o cenário, leia a mensagem de erro inteira, registre hipóteses e teste uma coisa por vez. Debug é método, não adivinhação.', bridge: 'Essa autonomia cresce muito quando você aprende a ler código que não foi escrito por você.' },
  { id: 'mt-reading-other-code', slugPt: 'como-ler-codigo-de-outra-pessoa-sem-se-perder', slugEn: 'how-to-read-other-peoples-code', title: { pt: 'Como Ler Código de Outra Pessoa Sem Se Perder', en: 'How to Read Someone Else Code Without Getting Lost' }, excerpt: { pt: 'Entrar em um projeto existente exige método. Antes de criticar o código, você precisa entender o motivo de ele estar daquele jeito.', en: 'Joining an existing project requires method. Before judging the code, you need to understand why it looks that way.' }, readTime: '15 min', tags: { pt: ['Código', 'Manutenção', 'Equipe'], en: ['Code', 'Maintenance', 'Team'] }, keywords: { pt: ['ler código legado', 'manutenção de software', 'entrar em projeto'], en: ['reading legacy code', 'software maintenance', 'joining projects'] }, subject: 'leitura de código existente', angle: 'Ler código dos outros é uma das habilidades menos ensinadas e mais usadas. A maior parte do trabalho real acontece em sistemas que já existem.', work: 'Você percebe isso quando entra em uma empresa, pega uma tarefa simples e descobre que a regra passa por vários arquivos, nomes antigos e decisões históricas.', mistake: 'achar que todo código diferente do seu está errado', practice: 'Comece pelo fluxo do usuário, siga a entrada e a saída dos dados, anote dúvidas e só depois proponha mudança. Entendimento vem antes de opinião.', bridge: 'Depois de entender sistemas existentes, fica mais fácil perceber por que testes deixam de ser luxo e viram proteção.' },
  { id: 'mt-tests-are-not-luxury', slugPt: 'por-que-testes-nao-sao-luxo-de-empresa-grande', slugEn: 'why-tests-are-not-a-big-company-luxury', title: { pt: 'Por Que Testes Não São Um Luxo de Empresa Grande', en: 'Why Tests Are Not a Big Company Luxury' }, excerpt: { pt: 'Testes não existem para agradar ferramenta. Eles protegem mudança, reduzem medo e dão confiança para evoluir software.', en: 'Tests do not exist to please tooling. They protect change, reduce fear and give confidence to evolve software.' }, readTime: '15 min', tags: { pt: ['Testes', 'Qualidade', 'Manutenção'], en: ['Tests', 'Quality', 'Maintenance'] }, keywords: { pt: ['testes automatizados', 'qualidade de software', 'manutenção'], en: ['automated tests', 'software quality', 'maintenance'] }, subject: 'testes automatizados', angle: 'O iniciante costuma enxergar teste como algo que atrasa. Depois que trabalha em projeto real, percebe que teste é o que permite mexer sem medo.', work: 'Isso aparece quando uma alteração pequena quebra uma regra antiga, quando ninguém sabe validar tudo manualmente ou quando o deploy vira aposta.', mistake: 'deixar teste para quando o projeto ficar grande', practice: 'Comece testando regras críticas, funções puras e fluxos que já quebraram antes. Cobertura útil nasce de risco real, não de vaidade.', bridge: 'A mesma lógica de pensar antes aparece no banco de dados. Tabela mal pensada cobra juros por muito tempo.' },
  { id: 'mt-database-before-tables', slugPt: 'como-pensar-em-banco-de-dados-antes-de-criar-tabelas', slugEn: 'how-to-think-about-databases-before-tables', title: { pt: 'Como Pensar em Banco de Dados Antes de Criar Tabelas', en: 'How to Think About Databases Before Creating Tables' }, excerpt: { pt: 'Banco de dados não é só lugar para guardar informação. Ele reflete regras, relações e decisões que sustentam o sistema.', en: 'A database is not just a place to store information. It reflects rules, relationships and decisions that support the system.' }, readTime: '16 min', tags: { pt: ['Banco de Dados', 'Arquitetura', 'Backend'], en: ['Database', 'Architecture', 'Backend'] }, keywords: { pt: ['modelagem de dados', 'banco de dados', 'tabelas'], en: ['data modeling', 'database', 'tables'] }, subject: 'modelagem de dados', angle: 'Criar tabela é fácil. Difícil é entender quais relações existem, quais dados mudam, quais precisam de histórico e quais nunca deveriam ser duplicados.', work: 'No trabalho, uma modelagem ruim aparece em relatório impossível, consulta lenta, dado inconsistente e regra espalhada pelo código.', mistake: 'começar pelo nome das tabelas antes de entender o processo', practice: 'Desenhe entidades, relações e estados antes do SQL. Pergunte o que acontece quando o dado muda e quem depende dele.', bridge: 'Depois do banco, a próxima fronteira natural é entender como sistemas conversam por APIs.' },
  { id: 'mt-clear-api-contracts', slugPt: 'o-que-toda-api-deveria-deixar-claro', slugEn: 'what-every-api-should-make-clear', title: { pt: 'O Que Toda API Deveria Deixar Claro', en: 'What Every API Should Make Clear' }, excerpt: { pt: 'Uma boa API comunica limites, erros, regras e expectativas. Quando isso falta, a integração vira adivinhação.', en: 'A good API communicates limits, errors, rules and expectations. Without that, integration becomes guesswork.' }, readTime: '15 min', tags: { pt: ['APIs', 'Integração', 'Backend'], en: ['APIs', 'Integration', 'Backend'] }, keywords: { pt: ['design de api', 'contrato de api', 'integração'], en: ['api design', 'api contract', 'integration'] }, subject: 'contratos de API', angle: 'API não é apenas endpoint respondendo JSON. É um acordo entre sistemas. Se esse acordo não está claro, cada lado interpreta de um jeito.', work: 'Isso aparece quando frontend não sabe o que fazer com erro, cliente integra errado ou uma mudança quebra consumidores sem aviso.', mistake: 'documentar só o caminho feliz', practice: 'Descreva autenticação, erros, limites, paginação, exemplos reais e mudanças esperadas. Uma API boa reduz conversa repetida.', bridge: 'Quando contratos ficam claros, o próximo desafio é evitar que projetos pequenos cresçam sem estrutura.' },
  { id: 'mt-small-project-chaos', slugPt: 'como-evitar-que-projeto-pequeno-vire-caos', slugEn: 'how-to-stop-small-projects-from-becoming-chaos', title: { pt: 'Como Evitar Que Um Projeto Pequeno Vire Um Caos', en: 'How to Stop a Small Project From Becoming Chaos' }, excerpt: { pt: 'Todo sistema grande já foi pequeno. O problema começa quando ninguém prepara o projeto para crescer um pouco mais.', en: 'Every large system was once small. The problem starts when nobody prepares the project to grow a little more.' }, readTime: '14 min', tags: { pt: ['Arquitetura', 'Organização', 'Projetos'], en: ['Architecture', 'Organization', 'Projects'] }, keywords: { pt: ['organização de projeto', 'arquitetura simples', 'manutenção'], en: ['project organization', 'simple architecture', 'maintenance'] }, subject: 'estrutura de projeto', angle: 'Projetos pequenos não precisam de arquitetura exagerada. Mas precisam de uma organização mínima para não virar um amontoado de decisões improvisadas.', work: 'Isso aparece quando cada nova funcionalidade exige mexer em lugares aleatórios e ninguém sabe onde determinada regra deveria morar.', mistake: 'confundir simplicidade com ausência de critério', practice: 'Separe responsabilidades, escolha nomes claros, documente decisões principais e evite criar abstração sem necessidade real.', bridge: 'Mesmo com organização, você só entende o sistema de verdade quando ele começa a falar por meio dos logs.' },
  { id: 'mt-logs-save-time', slugPt: 'por-que-logs-salvam-mais-tempo-do-que-voce-imagina', slugEn: 'why-logs-save-more-time-than-you-think', title: { pt: 'Por Que Logs Salvam Mais Tempo Do Que Você Imagina', en: 'Why Logs Save More Time Than You Think' }, excerpt: { pt: 'Logs bem pensados reduzem investigação cega, ajudam em incidentes e mostram como o sistema se comporta fora da sua máquina.', en: 'Well designed logs reduce blind investigation, help during incidents and show how the system behaves outside your machine.' }, readTime: '13 min', tags: { pt: ['Logs', 'Observabilidade', 'Debug'], en: ['Logs', 'Observability', 'Debug'] }, keywords: { pt: ['logs de aplicação', 'observabilidade', 'debug em produção'], en: ['application logs', 'observability', 'production debugging'] }, subject: 'logs úteis', angle: 'Log não é console jogado no código. É rastro de decisão. Quando algo quebra, ele precisa explicar o que aconteceu sem expor dado sensível.', work: 'Isso aparece em falha de pagamento, job que parou, usuário que não recebeu retorno ou integração que respondeu algo inesperado.', mistake: 'registrar informação demais ou informação que não ajuda', practice: 'Inclua contexto, identificador de operação, status e motivo do erro. Evite tokens, senhas, documentos e qualquer dado desnecessário.', bridge: 'Com informação melhor, fica mais fácil decidir quando resolver rápido e quando resolver direito.' },
  { id: 'mt-fast-vs-right', slugPt: 'como-decidir-entre-resolver-rapido-e-resolver-direito', slugEn: 'how-to-decide-between-fast-and-right', title: { pt: 'Como Decidir Entre Resolver Rápido e Resolver Direito', en: 'How to Decide Between Solving Fast and Solving Right' }, excerpt: { pt: 'Nem toda solução rápida é gambiarra e nem toda solução robusta é inteligente. O contexto decide o peso da escolha.', en: 'Not every fast solution is a hack and not every robust solution is smart. Context defines the weight of the choice.' }, readTime: '14 min', tags: { pt: ['Decisão Técnica', 'Arquitetura', 'Produto'], en: ['Technical Decision', 'Architecture', 'Product'] }, keywords: { pt: ['tradeoff técnico', 'decisão técnica', 'gambiarra'], en: ['technical tradeoff', 'technical decision', 'hack'] }, subject: 'decisão sob restrição', angle: 'Desenvolvimento real é feito de escolhas incompletas. Sempre existe prazo, risco, orçamento, gente esperando e informação que ainda não apareceu.', work: 'Isso aparece quando uma correção precisa ir para produção hoje, mas a causa raiz exige uma mudança maior.', mistake: 'chamar toda solução rápida de erro ou toda solução longa de qualidade', practice: 'Separe contenção de correção definitiva. Registre por que a decisão foi tomada e qual dívida precisa ser revisitada depois.', bridge: 'Para tomar decisões melhores, conhecer Linux ajuda mais do que muita gente imagina.' },
  { id: 'mt-linux-for-web-devs', slugPt: 'o-que-aprender-sobre-linux-mesmo-trabalhando-com-web', slugEn: 'what-to-learn-about-linux-even-as-a-web-dev', title: { pt: 'O Que Aprender Sobre Linux Mesmo Trabalhando Com Web', en: 'What to Learn About Linux Even as a Web Developer' }, excerpt: { pt: 'Você não precisa virar administrador de sistemas, mas entender Linux melhora deploy, debug, permissões e leitura de ambiente.', en: 'You do not need to become a system administrator, but understanding Linux improves deploy, debug, permissions and environment reading.' }, readTime: '15 min', tags: { pt: ['Linux', 'Infraestrutura', 'Backend'], en: ['Linux', 'Infrastructure', 'Backend'] }, keywords: { pt: ['linux para dev', 'terminal', 'deploy'], en: ['linux for developers', 'terminal', 'deploy'] }, subject: 'Linux no trabalho de desenvolvimento', angle: 'Muita gente aprende framework antes de entender o ambiente onde o código roda. Isso funciona até o primeiro problema de permissão, processo, porta ou variável.', work: 'No trabalho, Linux aparece em servidor, container, pipeline, log, shell, deploy e investigação de erro em produção.', mistake: 'usar terminal apenas copiando comando sem entender consequência', practice: 'Aprenda navegação, permissões, processos, variáveis de ambiente, logs, rede básica e leitura de arquivos. Pouco conhecimento já evita muito desespero.', bridge: 'Depois de entender o ambiente, deploy deixa de parecer mágica e começa a parecer processo.' },
  { id: 'mt-deploy-without-platform-dependence', slugPt: 'como-entender-deploy-sem-virar-refem-de-plataforma', slugEn: 'how-to-understand-deploy-without-platform-dependence', title: { pt: 'Como Entender Deploy Sem Virar Refém de Plataforma', en: 'How to Understand Deploy Without Becoming Platform Dependent' }, excerpt: { pt: 'Plataformas ajudam, mas o desenvolvedor precisa entender o que acontece entre o código sair do repositório e chegar ao usuário.', en: 'Platforms help, but developers need to understand what happens between code leaving the repository and reaching the user.' }, readTime: '16 min', tags: { pt: ['Deploy', 'DevOps', 'Infraestrutura'], en: ['Deploy', 'DevOps', 'Infrastructure'] }, keywords: { pt: ['deploy', 'ci cd', 'plataformas de hospedagem'], en: ['deploy', 'ci cd', 'hosting platforms'] }, subject: 'deploy consciente', angle: 'Deploy não é apertar um botão. O botão só esconde build, variáveis, ambiente, cache, rotas, arquivos estáticos e processo de publicação.', work: 'Isso aparece quando a aplicação funciona localmente, mas quebra na plataforma por diferença de ambiente ou configuração ausente.', mistake: 'confiar na plataforma sem entender o fluxo mínimo', practice: 'Mapeie build, runtime, variáveis, banco, logs e rollback. Se souber explicar o caminho do código até produção, você depende menos da interface.', bridge: 'Com deploy mais claro, performance passa a ser uma conversa mais séria do que apenas deixar algo rápido no final.' },
  { id: 'mt-performance-before-optimization', slugPt: 'por-que-performance-comeca-antes-da-otimizacao', slugEn: 'why-performance-starts-before-optimization', title: { pt: 'Por Que Performance Começa Antes da Otimização', en: 'Why Performance Starts Before Optimization' }, excerpt: { pt: 'Performance não é só mexer no final. Muitas decisões lentas nascem no desenho da solução, na consulta e na experiência.', en: 'Performance is not only a final adjustment. Many slow decisions are born in solution design, queries and experience.' }, readTime: '15 min', tags: { pt: ['Performance', 'Arquitetura', 'Web'], en: ['Performance', 'Architecture', 'Web'] }, keywords: { pt: ['performance web', 'otimização', 'arquitetura'], en: ['web performance', 'optimization', 'architecture'] }, subject: 'performance desde o desenho', angle: 'Otimizar depois ajuda, mas não corrige todas as decisões ruins. Muitas lentidões aparecem porque o sistema foi desenhado para fazer trabalho desnecessário.', work: 'Isso aparece em página carregando dados demais, consulta sem índice, imagem pesada, renderização cara ou fluxo que exige passos demais do usuário.', mistake: 'esperar o sistema ficar lento para pensar em performance', practice: 'Meça antes de mexer, reduza trabalho inútil, priorize o caminho crítico e escolha métricas que representem experiência real.', bridge: 'Pensar em performance também ajuda a reconhecer código que vai cobrar manutenção ruim.' },
  { id: 'mt-bad-maintenance-code', slugPt: 'como-identificar-codigo-que-vai-dar-manutencao-ruim', slugEn: 'how-to-identify-code-that-will-be-hard-to-maintain', title: { pt: 'Como Identificar Código Que Vai Dar Manutenção Ruim', en: 'How to Identify Code That Will Be Hard to Maintain' }, excerpt: { pt: 'Alguns sinais aparecem cedo. Dependência escondida, regra duplicada e nome confuso costumam prever dor futura.', en: 'Some signs appear early. Hidden dependency, duplicated rule and confusing naming often predict future pain.' }, readTime: '14 min', tags: { pt: ['Código', 'Manutenção', 'Qualidade'], en: ['Code', 'Maintenance', 'Quality'] }, keywords: { pt: ['código ruim', 'manutenção', 'qualidade de código'], en: ['bad code', 'maintenance', 'code quality'] }, subject: 'manutenção de código', angle: 'Código difícil raramente nasce difícil de propósito. Ele nasce de pressa, falta de clareza e pequenas exceções que ninguém voltou para organizar.', work: 'No trabalho, isso aparece quando uma mudança simples exige medo, porque ninguém sabe quais efeitos colaterais ela pode causar.', mistake: 'avaliar código só por funcionar hoje', practice: 'Procure regra duplicada, acoplamento invisível, nomes vagos, funções longas e decisões sem registro. Corrigir cedo é mais barato.', bridge: 'A qualidade do código importa porque software é feito para pessoas reais, não para impressionar a ferramenta.' },
  { id: 'mt-software-for-real-people', slugPt: 'o-que-significa-escrever-software-para-pessoas-reais', slugEn: 'what-it-means-to-write-software-for-real-people', title: { pt: 'O Que Significa Escrever Software Para Pessoas Reais', en: 'What It Means to Write Software for Real People' }, excerpt: { pt: 'Software profissional precisa considerar medo, pressa, erro humano, acessibilidade, suporte e consequência de cada decisão.', en: 'Professional software needs to consider fear, hurry, human error, accessibility, support and the consequence of each decision.' }, readTime: '14 min', tags: { pt: ['Produto', 'Usuário', 'Responsabilidade'], en: ['Product', 'User', 'Responsibility'] }, keywords: { pt: ['software para usuários', 'produto digital', 'responsabilidade técnica'], en: ['software for users', 'digital product', 'technical responsibility'] }, subject: 'software para usuários reais', angle: 'Usuário real não usa sistema como desenvolvedor imagina. Ele erra, tem pressa, lê pouco, usa celular ruim e precisa confiar no que está acontecendo.', work: 'Isso aparece em formulário confuso, mensagem de erro inútil, fluxo sem confirmação ou sistema que pune o usuário por não conhecer a regra interna.', mistake: 'projetar para quem sabe como o sistema foi construído', practice: 'Observe o uso real, escreva mensagens claras, trate erro com respeito e reduza decisão desnecessária. Interface também é responsabilidade técnica.', bridge: 'Essa responsabilidade fica ainda mais importante quando a IA entra no processo de desenvolvimento.' },
  { id: 'mt-using-ai-without-outsourcing-thinking', slugPt: 'como-usar-ia-sem-terceirizar-raciocinio', slugEn: 'how-to-use-ai-without-outsourcing-thinking', title: { pt: 'Como Usar IA Sem Terceirizar Seu Raciocínio', en: 'How to Use AI Without Outsourcing Your Thinking' }, excerpt: { pt: 'IA pode acelerar pesquisa, comparação e rascunho, mas não pode substituir sua responsabilidade sobre o que vai para produção.', en: 'AI can speed up research, comparison and drafts, but it cannot replace your responsibility for what goes to production.' }, readTime: '15 min', tags: { pt: ['Inteligência Artificial', 'Carreira', 'Responsabilidade'], en: ['Artificial Intelligence', 'Career', 'Responsibility'] }, keywords: { pt: ['ia para devs', 'uso de inteligência artificial', 'produtividade'], en: ['ai for developers', 'using artificial intelligence', 'productivity'] }, subject: 'uso responsável de IA', angle: 'Usar IA não é problema. O problema é deixar de pensar porque a resposta veio bonita. Código gerado continua sendo sua responsabilidade.', work: 'Isso aparece quando uma sugestão parece correta, passa no olhar rápido e depois falha em segurança, performance ou regra de negócio.', mistake: 'confundir resposta convincente com resposta validada', practice: 'Use IA para explorar caminhos, revisar hipóteses e acelerar rascunho. Depois leia, teste, simplifique e assuma a decisão.', bridge: 'Essa postura se conecta diretamente com segurança, que precisa entrar antes do primeiro incidente.' },
  { id: 'mt-security-at-project-start', slugPt: 'por-que-seguranca-precisa-entrar-no-inicio-do-projeto', slugEn: 'why-security-must-start-at-the-beginning', title: { pt: 'Por Que Segurança Precisa Entrar no Início do Projeto', en: 'Why Security Must Start at the Beginning of a Project' }, excerpt: { pt: 'Segurança colocada apenas no fim vira remendo. Quando entra cedo, ela orienta autenticação, dados, permissões e fluxo.', en: 'Security added only at the end becomes patchwork. When it starts early, it guides authentication, data, permissions and flow.' }, readTime: '16 min', tags: { pt: ['Segurança', 'Arquitetura', 'LGPD'], en: ['Security', 'Architecture', 'LGPD'] }, keywords: { pt: ['segurança em software', 'lgpd', 'autenticação'], en: ['software security', 'lgpd', 'authentication'] }, subject: 'segurança desde o começo', angle: 'Segurança não é camada decorativa. Ela muda como você guarda dados, valida acesso, registra eventos e responde a falhas.', work: 'Isso aparece quando um sistema cresce e descobre tarde que qualquer usuário consegue acessar coisa que não deveria.', mistake: 'tratar segurança como etapa final antes do deploy', practice: 'Comece pelo que precisa ser protegido, quem pode acessar, como auditar e qual dano ocorre se algo vazar.', bridge: 'Depois da segurança, cache é outro tema que parece simples até virar fonte de inconsistência.' },
  { id: 'mt-cache-without-new-problems', slugPt: 'como-pensar-em-cache-sem-criar-problema-novo', slugEn: 'how-to-think-about-cache-without-creating-new-problems', title: { pt: 'Como Pensar em Cache Sem Criar Problema Novo', en: 'How to Think About Cache Without Creating New Problems' }, excerpt: { pt: 'Cache melhora performance, mas também pode entregar dado velho, esconder bug e complicar invalidação quando é usado sem critério.', en: 'Cache improves performance, but it can also serve stale data, hide bugs and complicate invalidation when used without criteria.' }, readTime: '15 min', tags: { pt: ['Cache', 'Performance', 'Arquitetura'], en: ['Cache', 'Performance', 'Architecture'] }, keywords: { pt: ['cache', 'invalidação de cache', 'performance'], en: ['cache', 'cache invalidation', 'performance'] }, subject: 'cache com critério', angle: 'Cache parece solução mágica até o dia em que o usuário vê informação antiga e ninguém sabe de onde ela veio.', work: 'No trabalho, ele aparece em páginas lentas, APIs caras, listas repetidas e dados que mudam com menos frequência do que são lidos.', mistake: 'colocar cache antes de entender o custo e a validade do dado', practice: 'Defina o que pode ficar velho, por quanto tempo, quem invalida e como investigar quando o cache mentir.', bridge: 'Muitos problemas de escala pedem outro mecanismo além de cache, e é aí que filas entram na conversa.' },
  { id: 'mt-queues-and-async-processing', slugPt: 'o-que-aprender-sobre-filas-e-processamento-assincrono', slugEn: 'what-to-learn-about-queues-and-async-processing', title: { pt: 'O Que Aprender Sobre Filas e Processamento Assíncrono', en: 'What to Learn About Queues and Async Processing' }, excerpt: { pt: 'Filas ajudam a separar tempo de resposta de trabalho pesado, mas exigem cuidado com retry, ordem, falha e idempotência.', en: 'Queues help separate response time from heavy work, but require care with retry, ordering, failure and idempotency.' }, readTime: '16 min', tags: { pt: ['Filas', 'Arquitetura', 'Backend'], en: ['Queues', 'Architecture', 'Backend'] }, keywords: { pt: ['filas', 'processamento assíncrono', 'workers'], en: ['queues', 'async processing', 'workers'] }, subject: 'processamento assíncrono', angle: 'Nem todo trabalho precisa acontecer enquanto o usuário espera. Saber separar o que é imediato do que pode ir para fila muda a experiência e a estabilidade.', work: 'Isso aparece em envio de e-mail, processamento de imagem, relatório, cobrança, integração externa e tarefas longas.', mistake: 'usar fila como depósito de problema mal entendido', practice: 'Pense em retry, duplicidade, ordem, monitoramento e compensação. Fila resolve tempo de resposta, não elimina regra de negócio.', bridge: 'Quando decisões assim aparecem, documentar o motivo evita que a equipe esqueça o raciocínio.' },
  { id: 'mt-documenting-technical-decisions', slugPt: 'como-documentar-decisao-tecnica-sem-enrolar', slugEn: 'how-to-document-technical-decisions-without-padding', title: { pt: 'Como Documentar Uma Decisão Técnica Sem Enrolar', en: 'How to Document a Technical Decision Without Padding' }, excerpt: { pt: 'Documentação boa não é texto enorme. É registro claro do problema, das opções consideradas e do motivo da escolha.', en: 'Good documentation is not huge text. It is a clear record of the problem, the options considered and the reason for the choice.' }, readTime: '13 min', tags: { pt: ['Documentação', 'Arquitetura', 'Equipe'], en: ['Documentation', 'Architecture', 'Team'] }, keywords: { pt: ['documentar decisão técnica', 'adr', 'documentação'], en: ['documenting technical decisions', 'adr', 'documentation'] }, subject: 'registro de decisão', angle: 'Toda decisão técnica importante envelhece. Se ninguém registra o motivo, o futuro interpreta a escolha como erro ou capricho.', work: 'Isso aparece quando alguém pergunta por que a stack foi escolhida, por que uma regra existe ou por que uma limitação foi aceita.', mistake: 'documentar só depois que a memória já falhou', practice: 'Registre problema, alternativas, escolha, motivo, impacto e ponto de revisão. Poucas linhas bem escritas economizam muitas reuniões.', bridge: 'Essa clareza também melhora revisão de código, que deveria ser conversa técnica e não disputa de ego.' },
  { id: 'mt-code-review-not-personal-attack', slugPt: 'por-que-revisao-de-codigo-nao-e-ataque-pessoal', slugEn: 'why-code-review-is-not-a-personal-attack', title: { pt: 'Por Que Revisão de Código Não É Ataque Pessoal', en: 'Why Code Review Is Not a Personal Attack' }, excerpt: { pt: 'Review bom protege o produto, ensina a equipe e melhora consistência. O problema começa quando crítica técnica vira ameaça ao ego.', en: 'Good review protects the product, teaches the team and improves consistency. The problem starts when technical critique threatens ego.' }, readTime: '14 min', tags: { pt: ['Code Review', 'Equipe', 'Maturidade'], en: ['Code Review', 'Team', 'Maturity'] }, keywords: { pt: ['revisão de código', 'pull request', 'trabalho em equipe'], en: ['code review', 'pull request', 'teamwork'] }, subject: 'revisão de código', angle: 'Review não existe para provar quem sabe mais. Existe para reduzir risco antes que o código vire responsabilidade de todo mundo.', work: 'Isso aparece em pull request com regra quebrada, nome confuso, teste ausente ou decisão que precisa ser explicada para a equipe.', mistake: 'defender cada linha como se fosse parte da identidade pessoal', practice: 'Peça contexto, explique motivo, diferencie gosto de risco e aceite que melhorar código não diminui quem escreveu.', bridge: 'Depois que a pessoa entra no mercado, esse tipo de maturidade pesa muito na evolução após a primeira vaga.' },
  { id: 'mt-after-first-job', slugPt: 'como-evoluir-depois-da-primeira-vaga', slugEn: 'how-to-grow-after-your-first-job', title: { pt: 'Como Evoluir Depois da Primeira Vaga', en: 'How to Grow After Your First Job' }, excerpt: { pt: 'Conseguir a primeira vaga não encerra a fase difícil. Ela muda o tipo de cobrança e exige evolução mais consciente.', en: 'Getting the first job does not end the hard phase. It changes the kind of pressure and demands more conscious growth.' }, readTime: '14 min', tags: { pt: ['Carreira', 'Primeira Vaga', 'Evolução'], en: ['Career', 'First Job', 'Growth'] }, keywords: { pt: ['primeira vaga dev', 'crescer na carreira', 'júnior'], en: ['first dev job', 'career growth', 'junior'] }, subject: 'crescimento depois da primeira vaga', angle: 'A primeira vaga resolve uma ansiedade, mas cria outra. Agora não basta estudar para entrar. Você precisa aprender a entregar dentro de um contexto real.', work: 'Isso aparece quando tarefas têm prazo, revisão, legado, dependência de outras áreas e impacto em usuário de verdade.', mistake: 'parar de estudar porque já conseguiu entrar', practice: 'Observe seniors, peça feedback específico, registre dúvidas, entenda o domínio do produto e melhore uma habilidade por ciclo.', bridge: 'Para crescer nessa fase, um júnior precisa provar coisas que vão além de saber escrever código.' },
  { id: 'mt-what-junior-must-prove', slugPt: 'o-que-um-junior-precisa-provar-no-dia-a-dia', slugEn: 'what-a-junior-must-prove-every-day', title: { pt: 'O Que Um Júnior Precisa Provar No Dia a Dia', en: 'What a Junior Developer Must Prove Every Day' }, excerpt: { pt: 'O júnior não precisa saber tudo. Precisa mostrar evolução, responsabilidade, comunicação e capacidade de aprender com o trabalho.', en: 'A junior does not need to know everything. They need to show growth, responsibility, communication and ability to learn from work.' }, readTime: '13 min', tags: { pt: ['Júnior', 'Carreira', 'Equipe'], en: ['Junior', 'Career', 'Team'] }, keywords: { pt: ['desenvolvedor júnior', 'primeiro emprego', 'postura profissional'], en: ['junior developer', 'first job', 'professional attitude'] }, subject: 'postura de júnior', angle: 'Empresa não espera que júnior resolva tudo sozinho. Mas espera que ele aprenda, comunique bloqueios e não esconda problema.', work: 'Isso aparece em tarefa que atrasou, bug que voltou, dúvida que não foi feita e decisão tomada sem contexto suficiente.', mistake: 'fingir domínio para não parecer iniciante', practice: 'Mostre progresso, peça ajuda com contexto, anote feedback e entregue pequenas melhorias consistentes. Confiança nasce de previsibilidade.', bridge: 'Feedback é parte central desse processo, mas muita gente escuta feedback como ofensa e perde oportunidade de crescer.' },
  { id: 'mt-feedback-into-growth', slugPt: 'como-transformar-feedback-em-crescimento-real', slugEn: 'how-to-turn-feedback-into-real-growth', title: { pt: 'Como Transformar Feedback Em Crescimento Real', en: 'How to Turn Feedback Into Real Growth' }, excerpt: { pt: 'Feedback só vira evolução quando você separa desconforto de informação útil e muda comportamento observável.', en: 'Feedback becomes growth only when you separate discomfort from useful information and change observable behavior.' }, readTime: '13 min', tags: { pt: ['Feedback', 'Carreira', 'Maturidade'], en: ['Feedback', 'Career', 'Maturity'] }, keywords: { pt: ['receber feedback', 'crescimento profissional', 'maturidade'], en: ['receiving feedback', 'professional growth', 'maturity'] }, subject: 'uso de feedback', angle: 'Feedback bom nem sempre vem confortável. Às vezes ele mostra exatamente o ponto que você evitava encarar.', work: 'Isso aparece em review, reunião de alinhamento, avaliação de desempenho e comentário de cliente sobre algo que não ficou claro.', mistake: 'responder feedback tentando se defender antes de entender', practice: 'Anote o ponto, peça exemplo, transforme em ação pequena e volte depois mostrando o que mudou. Feedback sem ação vira conversa repetida.', bridge: 'Crescer também depende de como você se apresenta publicamente, e o LinkedIn entra nessa parte da carreira.' },
  { id: 'mt-linkedin-with-criteria', slugPt: 'por-que-seu-linkedin-precisa-mostrar-criterio', slugEn: 'why-your-linkedin-needs-to-show-judgment', title: { pt: 'Por Que Seu LinkedIn Precisa Mostrar Critério', en: 'Why Your LinkedIn Needs to Show Judgment' }, excerpt: { pt: 'LinkedIn não precisa ser palco artificial. Ele precisa mostrar com clareza quem você é, o que sabe construir e como pensa.', en: 'LinkedIn does not need to be an artificial stage. It needs to show clearly who you are, what you can build and how you think.' }, readTime: '14 min', tags: { pt: ['LinkedIn', 'Carreira', 'Posicionamento'], en: ['LinkedIn', 'Career', 'Positioning'] }, keywords: { pt: ['linkedin para dev', 'posicionamento profissional', 'perfil técnico'], en: ['linkedin for developers', 'professional positioning', 'technical profile'] }, subject: 'perfil profissional', angle: 'Um perfil profissional não precisa gritar. Precisa ser coerente. Quem lê deve entender sua direção, sua experiência e seu nível de critério.', work: 'Isso aparece quando recrutador, cliente ou parceiro visita seu perfil antes de responder uma conversa.', mistake: 'encher o perfil de palavras bonitas sem evidência', practice: 'Mostre projetos, decisões, aprendizados e áreas de interesse. Escreva como pessoa real, não como anúncio de si mesmo.', bridge: 'Um perfil claro ajuda, mas relacionamento profissional não nasce apenas de vitrine. Networking precisa de presença real.' },
  { id: 'mt-networking-without-forcing', slugPt: 'como-fazer-networking-sem-forcar-intimidade', slugEn: 'how-to-network-without-forcing-intimacy', title: { pt: 'Como Fazer Networking Sem Forçar Intimidade', en: 'How to Network Without Forcing Intimacy' }, excerpt: { pt: 'Networking bom não é pedir favor para desconhecido. É construir presença, contribuir e manter relações com respeito.', en: 'Good networking is not asking strangers for favors. It is building presence, contributing and maintaining relationships with respect.' }, readTime: '13 min', tags: { pt: ['Networking', 'Comunicação', 'Carreira'], en: ['Networking', 'Communication', 'Career'] }, keywords: { pt: ['networking dev', 'relacionamento profissional', 'comunidades'], en: ['developer networking', 'professional relationships', 'communities'] }, subject: 'relacionamento profissional', angle: 'Networking forçado parece abordagem de venda. Networking real nasce quando você participa, ajuda, conversa e aparece com consistência.', work: 'Isso aparece em comunidades, eventos, comentários técnicos, indicações e conversas que continuam depois do primeiro contato.', mistake: 'só aparecer quando precisa de vaga ou favor', practice: 'Comente com conteúdo, compartilhe aprendizado, agradeça ajuda, mantenha contato e respeite o tempo das pessoas.', bridge: 'Quando surge oportunidade, currículo precisa traduzir essa trajetória sem fingir experiência que ainda não existe.' },
  { id: 'mt-cv-with-little-experience', slugPt: 'o-que-colocar-no-curriculo-com-pouca-experiencia', slugEn: 'what-to-put-on-a-resume-with-little-experience', title: { pt: 'O Que Colocar No Currículo Quando Você Tem Pouca Experiência', en: 'What to Put on a Resume When You Have Little Experience' }, excerpt: { pt: 'Pouca experiência não significa currículo vazio. O que importa é mostrar evidência, foco e capacidade de entregar algo verificável.', en: 'Little experience does not mean an empty resume. What matters is showing evidence, focus and ability to deliver something verifiable.' }, readTime: '13 min', tags: { pt: ['Currículo', 'Primeira Vaga', 'Carreira'], en: ['Resume', 'First Job', 'Career'] }, keywords: { pt: ['currículo dev iniciante', 'primeira vaga', 'portfólio'], en: ['beginner dev resume', 'first job', 'portfolio'] }, subject: 'currículo de iniciante', angle: 'Currículo de iniciante precisa ser honesto e útil. Ele não deve tentar parecer sênior. Deve facilitar a avaliação do que você já consegue fazer.', work: 'Isso aparece quando recrutador tem poucos minutos para entender se vale abrir seu GitHub, portfólio ou chamar para conversa.', mistake: 'listar tecnologia sem contexto e sem projeto que prove uso', practice: 'Inclua projetos com problema, stack, responsabilidade e link. Mostre estudo sério, contribuição, documentação e resultado concreto.', bridge: 'Depois do currículo, o GitHub vira uma das provas mais acessíveis da sua maturidade.' },
  { id: 'mt-github-shows-maturity', slugPt: 'como-usar-github-para-mostrar-maturidade', slugEn: 'how-to-use-github-to-show-maturity', title: { pt: 'Como Usar GitHub Para Mostrar Maturidade', en: 'How to Use GitHub to Show Maturity' }, excerpt: { pt: 'GitHub não é depósito de qualquer coisa. Ele pode mostrar organização, evolução, documentação e cuidado com o próprio trabalho.', en: 'GitHub is not a dump for everything. It can show organization, evolution, documentation and care with your own work.' }, readTime: '14 min', tags: { pt: ['GitHub', 'Portfólio', 'Carreira'], en: ['GitHub', 'Portfolio', 'Career'] }, keywords: { pt: ['github profissional', 'portfolio dev', 'readme'], en: ['professional github', 'dev portfolio', 'readme'] }, subject: 'GitHub como evidência', angle: 'Seu GitHub não precisa ter cem repositórios. Precisa ter alguns projetos que alguém consiga entender sem pedir explicação.', work: 'Isso aparece quando avaliador abre seu perfil e decide em poucos minutos se existe cuidado técnico ali.', mistake: 'deixar repositório abandonado, sem README e com segredo exposto', practice: 'Fixe projetos bons, arquive ruído, escreva README útil, organize commits e trate segurança como parte da apresentação.', bridge: 'Quando essa apresentação começa a gerar demanda, freelancing surge como possibilidade, mas ele não começa pelo preço.' },
  { id: 'mt-freelancing-not-about-price', slugPt: 'por-que-freelancing-nao-comeca-com-preco', slugEn: 'why-freelancing-does-not-start-with-price', title: { pt: 'Por Que Freelancing Não Começa Com Preço', en: 'Why Freelancing Does Not Start With Price' }, excerpt: { pt: 'Antes de cobrar, você precisa entender problema, risco, escopo, responsabilidade e impacto. Preço vem depois do diagnóstico.', en: 'Before charging, you need to understand problem, risk, scope, responsibility and impact. Price comes after diagnosis.' }, readTime: '15 min', tags: { pt: ['Freelancer', 'Clientes', 'Negócios'], en: ['Freelance', 'Clients', 'Business'] }, keywords: { pt: ['freelancer dev', 'cobrar projeto', 'cliente'], en: ['freelance developer', 'pricing projects', 'client'] }, subject: 'freelancing com responsabilidade', angle: 'Muita gente começa perguntando quanto cobrar. A pergunta vem cedo demais. Sem entender o problema, qualquer valor é chute.', work: 'Isso aparece quando cliente pede site simples, mas por trás existe integração, conteúdo, prazo, manutenção e risco de negócio.', mistake: 'dar preço para agradar antes de saber o que será entregue', practice: 'Faça perguntas, delimite escopo, registre premissas, explique exclusões e só depois fale de valor.', bridge: 'Conversar com cliente exige essa clareza, principalmente quando ele ainda não sabe explicar o próprio problema.' },
  { id: 'mt-client-conversation-without-miracle', slugPt: 'como-conversar-com-cliente-sem-prometer-milagre', slugEn: 'how-to-talk-to-clients-without-promising-miracles', title: { pt: 'Como Conversar Com Cliente Sem Prometer Milagre', en: 'How to Talk to Clients Without Promising Miracles' }, excerpt: { pt: 'Cliente precisa de clareza, não de promessa bonita. A conversa profissional organiza expectativa antes de virar contrato.', en: 'Clients need clarity, not pretty promises. A professional conversation organizes expectations before becoming a contract.' }, readTime: '14 min', tags: { pt: ['Clientes', 'Comunicação', 'Freelancer'], en: ['Clients', 'Communication', 'Freelance'] }, keywords: { pt: ['conversar com cliente', 'escopo', 'proposta'], en: ['client conversation', 'scope', 'proposal'] }, subject: 'comunicação com cliente', angle: 'Prometer demais pode fechar conversa rápido, mas abre problema depois. Cliente sério valoriza quem explica limite antes de vender certeza.', work: 'Isso aparece em reunião de briefing, proposta comercial, ajuste de prazo e negociação de mudança de escopo.', mistake: 'responder com solução antes de entender objetivo', practice: 'Pergunte sobre resultado esperado, público, restrição, prazo, orçamento e operação depois da entrega.', bridge: 'Mesmo com boa conversa, muitas vezes o cliente não sabe o que quer. Nesse cenário, o trabalho começa pelo diagnóstico.' },
  { id: 'mt-client-does-not-know-what-they-want', slugPt: 'o-que-cobrar-quando-cliente-nao-sabe-o-que-quer', slugEn: 'what-to-charge-when-client-does-not-know-what-they-want', title: { pt: 'O Que Cobrar Quando o Cliente Não Sabe O Que Quer', en: 'What to Charge When the Client Does Not Know What They Want' }, excerpt: { pt: 'Quando o cliente não tem clareza, vender desenvolvimento direto pode ser erro. Às vezes o primeiro produto é diagnóstico.', en: 'When the client lacks clarity, selling development directly can be a mistake. Sometimes the first product is diagnosis.' }, readTime: '15 min', tags: { pt: ['Clientes', 'Consultoria', 'Escopo'], en: ['Clients', 'Consulting', 'Scope'] }, keywords: { pt: ['diagnóstico de projeto', 'escopo indefinido', 'consultoria'], en: ['project diagnosis', 'undefined scope', 'consulting'] }, subject: 'escopo indefinido', angle: 'Cliente confuso não é necessariamente cliente ruim. Muitas vezes ele conhece a dor, mas ainda não sabe traduzir em sistema.', work: 'Isso aparece quando a pessoa pede aplicativo, painel ou automação sem conseguir explicar processo, prioridade ou regra principal.', mistake: 'vender execução como se o problema já estivesse claro', practice: 'Ofereça etapa de descoberta, mapeie fluxo, entregue documento de escopo e só avance para desenvolvimento com base suficiente.', bridge: 'Depois do diagnóstico, estimar trabalho fica mais honesto e menos dependente de adivinhação.' },
  { id: 'mt-estimating-without-fake-certainty', slugPt: 'como-estimar-trabalho-sem-vender-certeza-falsa', slugEn: 'how-to-estimate-work-without-selling-fake-certainty', title: { pt: 'Como Estimar Trabalho Sem Vender Certeza Falsa', en: 'How to Estimate Work Without Selling Fake Certainty' }, excerpt: { pt: 'Estimativa não é promessa absoluta. É uma leitura técnica baseada em escopo, risco, experiência e margem de variação.', en: 'An estimate is not an absolute promise. It is a technical reading based on scope, risk, experience and margin of variation.' }, readTime: '15 min', tags: { pt: ['Estimativa', 'Projetos', 'Clientes'], en: ['Estimate', 'Projects', 'Clients'] }, keywords: { pt: ['estimar projeto', 'prazo de software', 'escopo'], en: ['estimating projects', 'software timeline', 'scope'] }, subject: 'estimativa de projeto', angle: 'Software tem incerteza. Quem vende certeza total antes de investigar está escondendo risco ou ainda não entendeu o trabalho.', work: 'Isso aparece em proposta, sprint, manutenção, integração externa e qualquer tarefa que dependa de sistema de terceiros.', mistake: 'transformar chute em compromisso rígido', practice: 'Separe conhecido de incerto, use faixas, exponha premissas e revise estimativa quando novas informações aparecerem.', bridge: 'Esse cuidado é parte da consultoria, que exige mais diagnóstico do que resposta rápida.' },
  { id: 'mt-consulting-needs-diagnosis', slugPt: 'por-que-consultoria-exige-mais-diagnostico-que-resposta', slugEn: 'why-consulting-needs-more-diagnosis-than-answer', title: { pt: 'Por Que Consultoria Exige Mais Diagnóstico Que Resposta', en: 'Why Consulting Needs More Diagnosis Than Answers' }, excerpt: { pt: 'Consultoria séria não chega entregando opinião pronta. Primeiro entende operação, restrição, risco e consequência.', en: 'Serious consulting does not arrive with a ready opinion. It first understands operation, restriction, risk and consequence.' }, readTime: '15 min', tags: { pt: ['Consultoria', 'Negócios', 'Arquitetura'], en: ['Consulting', 'Business', 'Architecture'] }, keywords: { pt: ['consultoria tech', 'diagnóstico técnico', 'estratégia'], en: ['tech consulting', 'technical diagnosis', 'strategy'] }, subject: 'consultoria técnica', angle: 'Resposta rápida impressiona, mas pode errar o alvo. Consultoria boa começa com escuta, leitura de cenário e clareza sobre o que não foi visto ainda.', work: 'Isso aparece quando empresa quer trocar stack, reescrever sistema, reduzir custo ou resolver gargalo operacional.', mistake: 'dar opinião forte com pouca informação', practice: 'Levante evidências, peça histórico, observe métricas, identifique restrições e apresente caminho com risco assumido claramente.', bridge: 'Com o tempo, esse tipo de postura constrói autoridade sem precisar criar personagem.' },
  { id: 'mt-authority-without-character', slugPt: 'como-construir-autoridade-sem-parecer-personagem', slugEn: 'how-to-build-authority-without-looking-like-a-character', title: { pt: 'Como Construir Autoridade Sem Parecer Um Personagem', en: 'How to Build Authority Without Looking Like a Character' }, excerpt: { pt: 'Autoridade profissional nasce de consistência, clareza e prova de trabalho. Não precisa virar performance artificial.', en: 'Professional authority comes from consistency, clarity and proof of work. It does not need to become artificial performance.' }, readTime: '13 min', tags: { pt: ['Autoridade', 'Conteúdo', 'Carreira'], en: ['Authority', 'Content', 'Career'] }, keywords: { pt: ['autoridade profissional', 'marca pessoal', 'conteúdo técnico'], en: ['professional authority', 'personal brand', 'technical content'] }, subject: 'autoridade profissional', angle: 'Autoridade não é falar alto. É ser lembrado quando determinado problema aparece porque você já demonstrou critério naquele assunto.', work: 'Isso aparece quando pessoas indicam seu conteúdo, procuram sua opinião ou confiam em você antes mesmo de uma reunião.', mistake: 'criar personagem para parecer maior do que é', practice: 'Publique aprendizados reais, mostre decisões, admita limites e mantenha coerência entre discurso, entrega e postura.', bridge: 'Mesmo com autoridade crescendo, a síndrome do impostor pode aparecer quando o nível de cobrança aumenta.' },
  { id: 'mt-impostor-syndrome-in-tech', slugPt: 'o-que-fazer-quando-voce-sente-sindrome-do-impostor', slugEn: 'what-to-do-when-you-feel-impostor-syndrome', title: { pt: 'O Que Fazer Quando Você Sente Síndrome do Impostor', en: 'What to Do When You Feel Impostor Syndrome' }, excerpt: { pt: 'Sentir insegurança não significa fraude. O problema é deixar a sensação comandar decisões, silêncio e comparação.', en: 'Feeling insecure does not mean being a fraud. The problem is letting the feeling drive decisions, silence and comparison.' }, readTime: '13 min', tags: { pt: ['Carreira', 'Autoconhecimento', 'Maturidade'], en: ['Career', 'Self Knowledge', 'Maturity'] }, keywords: { pt: ['síndrome do impostor', 'insegurança profissional', 'carreira dev'], en: ['impostor syndrome', 'professional insecurity', 'dev career'] }, subject: 'insegurança profissional', angle: 'A sensação de não estar pronto pode aparecer justamente quando você está crescendo. Ambientes novos expõem lacunas que antes ficavam escondidas.', work: 'Isso aparece em promoção, entrevista, projeto maior, reunião com cliente ou quando você começa a conviver com pessoas mais experientes.', mistake: 'usar insegurança como prova de incapacidade', practice: 'Compare evidências, registre evolução, peça feedback específico e separe o que você não sabe ainda do que você não é capaz de aprender.', bridge: 'Saúde na carreira também exige reconhecer limites antes que esforço constante vire burnout.' },
  { id: 'mt-avoid-burnout-without-productivity-romance', slugPt: 'como-evitar-burnout-sem-romantizar-produtividade', slugEn: 'how-to-avoid-burnout-without-romanticizing-productivity', title: { pt: 'Como Evitar Burnout Sem Romantizar Produtividade', en: 'How to Avoid Burnout Without Romanticizing Productivity' }, excerpt: { pt: 'Trabalhar muito não prova compromisso quando o custo é perder clareza, saúde e capacidade de sustentar qualidade.', en: 'Working a lot does not prove commitment when the cost is losing clarity, health and the ability to sustain quality.' }, readTime: '14 min', tags: { pt: ['Burnout', 'Produtividade', 'Carreira'], en: ['Burnout', 'Productivity', 'Career'] }, keywords: { pt: ['burnout tecnologia', 'produtividade saudável', 'rotina dev'], en: ['tech burnout', 'healthy productivity', 'dev routine'] }, subject: 'produtividade sustentável', angle: 'A área de tecnologia normalizou excesso com muita facilidade. O problema é que mente cansada toma decisão pior e código ruim também é consequência de desgaste.', work: 'Isso aparece em prazos longos demais, plantões, acúmulo de contexto, reuniões excessivas e tentativa de estudar como se o dia tivesse trinta horas.', mistake: 'confundir constância com exaustão', practice: 'Defina limite real, organize prioridades, proteja sono, reduza troca de contexto e trate descanso como parte da manutenção do profissional.', bridge: 'Essa organização pessoal afeta diretamente a qualidade do código que você entrega.' },
  { id: 'mt-personal-organization-code-quality', slugPt: 'por-que-organizacao-pessoal-afeta-qualidade-de-codigo', slugEn: 'why-personal-organization-affects-code-quality', title: { pt: 'Por Que Organização Pessoal Afeta Qualidade de Código', en: 'Why Personal Organization Affects Code Quality' }, excerpt: { pt: 'Código não nasce isolado. Agenda bagunçada, tarefa mal lida e prioridade confusa aparecem dentro da entrega.', en: 'Code is not born in isolation. Messy schedule, poorly read tasks and confused priorities appear inside the delivery.' }, readTime: '13 min', tags: { pt: ['Organização', 'Qualidade', 'Carreira'], en: ['Organization', 'Quality', 'Career'] }, keywords: { pt: ['organização pessoal', 'qualidade de código', 'produtividade dev'], en: ['personal organization', 'code quality', 'developer productivity'] }, subject: 'organização de trabalho', angle: 'Organização pessoal não é frescura de produtividade. É a forma como você protege atenção para resolver problemas difíceis.', work: 'Isso aparece quando tarefa é esquecida, contexto se perde, comunicação atrasa e implementação começa sem entendimento completo.', mistake: 'achar que talento compensa rotina desorganizada', practice: 'Mantenha fila de tarefas, registre decisão, quebre trabalho grande, revise prioridades e reduza interrupções quando precisar pensar.', bridge: 'Depois que você começa a trabalhar, estudar exige outro tipo de organização.' },
  { id: 'mt-study-routine-after-job', slugPt: 'como-criar-rotina-de-estudos-depois-de-comecar-a-trabalhar', slugEn: 'how-to-study-after-you-start-working', title: { pt: 'Como Criar Rotina de Estudos Depois de Começar a Trabalhar', en: 'How to Build a Study Routine After You Start Working' }, excerpt: { pt: 'Depois da primeira vaga, o estudo precisa conversar com o trabalho. Caso contrário, vira acúmulo de assunto sem aplicação.', en: 'After the first job, study needs to connect with work. Otherwise, it becomes accumulation without application.' }, readTime: '14 min', tags: { pt: ['Estudo', 'Carreira', 'Rotina'], en: ['Study', 'Career', 'Routine'] }, keywords: { pt: ['estudar trabalhando', 'rotina de estudos dev', 'evolução técnica'], en: ['studying while working', 'dev study routine', 'technical growth'] }, subject: 'estudo durante a carreira', angle: 'Estudar trabalhando é diferente de estudar para entrar no mercado. Agora você tem problemas reais para orientar o que precisa aprender.', work: 'Isso aparece quando uma tarefa expõe lacuna em banco, teste, arquitetura, comunicação ou domínio do negócio.', mistake: 'tentar manter a mesma rotina de quando tinha mais tempo livre', practice: 'Escolha temas ligados ao trabalho atual, estude em blocos menores e transforme cada aprendizado em melhoria aplicada.', bridge: 'Com o tempo, essa prática separa quem cresce como pleno de quem fica parado repetindo o mesmo repertório.' },
  { id: 'mt-mid-level-that-keeps-growing', slugPt: 'o-que-diferencia-um-pleno-que-cresce-de-um-pleno-que-para', slugEn: 'what-separates-a-growing-mid-level-from-a-stuck-one', title: { pt: 'O Que Diferencia Um Pleno Que Cresce de Um Pleno Que Para', en: 'What Separates a Growing Mid Level Developer From a Stuck One' }, excerpt: { pt: 'O pleno que continua evoluindo começa a pensar em impacto, manutenção, comunicação e decisões que atravessam a própria tarefa.', en: 'The mid level developer who keeps growing starts thinking about impact, maintenance, communication and decisions beyond the task.' }, readTime: '14 min', tags: { pt: ['Pleno', 'Carreira', 'Maturidade'], en: ['Mid Level', 'Career', 'Maturity'] }, keywords: { pt: ['desenvolvedor pleno', 'crescimento profissional', 'maturidade técnica'], en: ['mid level developer', 'professional growth', 'technical maturity'] }, subject: 'evolução de pleno', angle: 'Chegar a pleno não deveria virar zona de conforto. É justamente nessa fase que a pessoa precisa ampliar visão para além da própria entrega.', work: 'Isso aparece quando decisões técnicas começam a afetar equipe, prazo, produto e manutenção futura.', mistake: 'continuar medindo evolução só pela velocidade de implementar tarefa', practice: 'Assuma mais contexto, ajude pessoas, questione impacto e aprenda a explicar decisões para áreas não técnicas.', bridge: 'Essa ampliação naturalmente aproxima liderança, mesmo antes de existir cargo formal.' },
  { id: 'mt-leading-without-title', slugPt: 'como-comecar-a-liderar-mesmo-sem-cargo', slugEn: 'how-to-start-leading-without-a-title', title: { pt: 'Como Começar a Liderar Mesmo Sem Cargo', en: 'How to Start Leading Without a Title' }, excerpt: { pt: 'Liderança técnica começa quando você melhora clareza, reduz risco e ajuda outras pessoas a entregarem melhor.', en: 'Technical leadership starts when you improve clarity, reduce risk and help other people deliver better.' }, readTime: '14 min', tags: { pt: ['Liderança', 'Equipe', 'Carreira'], en: ['Leadership', 'Team', 'Career'] }, keywords: { pt: ['liderança técnica', 'liderar sem cargo', 'carreira dev'], en: ['technical leadership', 'leading without title', 'dev career'] }, subject: 'liderança sem cargo', angle: 'Cargo pode reconhecer liderança, mas não cria liderança sozinho. Antes do título, existe postura diante de problema, equipe e responsabilidade.', work: 'Isso aparece quando você organiza uma decisão, ajuda alguém travado, antecipa risco ou melhora comunicação entre áreas.', mistake: 'achar que liderar é mandar em pessoas', practice: 'Crie clareza, compartilhe contexto, faça perguntas melhores e assuma responsabilidade por melhorar o ambiente técnico ao redor.', bridge: 'A base disso é comunicação técnica, uma habilidade que muda o rumo da carreira.' },
  { id: 'mt-technical-communication-career', slugPt: 'por-que-comunicacao-tecnica-muda-sua-carreira', slugEn: 'why-technical-communication-changes-your-career', title: { pt: 'Por Que Comunicação Técnica Muda Sua Carreira', en: 'Why Technical Communication Changes Your Career' }, excerpt: { pt: 'Quem explica bem reduz ruído, ganha confiança e participa de decisões maiores. Código bom não compensa comunicação confusa.', en: 'People who explain well reduce noise, earn trust and join bigger decisions. Good code does not compensate for confusing communication.' }, readTime: '14 min', tags: { pt: ['Comunicação', 'Carreira', 'Equipe'], en: ['Communication', 'Career', 'Team'] }, keywords: { pt: ['comunicação técnica', 'explicar código', 'carreira'], en: ['technical communication', 'explaining code', 'career'] }, subject: 'comunicação técnica', angle: 'Desenvolvedor que comunica bem não parece melhor apenas porque fala bonito. Ele ajuda a equipe a tomar decisão com menos dúvida.', work: 'Isso aparece em PR, reunião, documentação, alinhamento com produto e conversa com cliente sobre limite técnico.', mistake: 'achar que o código deveria explicar tudo sozinho', practice: 'Explique problema, alternativa, impacto e risco em linguagem adequada para quem está ouvindo.', bridge: 'A próxima etapa é explicar decisão técnica para quem não programa, sem perder precisão.' },
  { id: 'mt-explaining-tech-to-non-devs', slugPt: 'como-explicar-decisao-tecnica-para-quem-nao-programa', slugEn: 'how-to-explain-technical-decisions-to-non-developers', title: { pt: 'Como Explicar Uma Decisão Técnica Para Quem Não Programa', en: 'How to Explain a Technical Decision to Non Developers' }, excerpt: { pt: 'Explicar técnica para pessoas de negócio exige traduzir impacto, risco e custo sem infantilizar o assunto.', en: 'Explaining technology to business people requires translating impact, risk and cost without oversimplifying the subject.' }, readTime: '14 min', tags: { pt: ['Comunicação', 'Negócios', 'Arquitetura'], en: ['Communication', 'Business', 'Architecture'] }, keywords: { pt: ['explicar tecnologia', 'decisão técnica', 'negócios'], en: ['explaining technology', 'technical decision', 'business'] }, subject: 'tradução técnica', angle: 'Quem não programa não precisa saber detalhes internos para tomar boa decisão. Precisa entender consequência.', work: 'Isso aparece quando você precisa justificar refatoração, prazo maior, troca de arquitetura ou recusa de uma solução aparentemente simples.', mistake: 'falar em jargão para parecer técnico', practice: 'Troque detalhe interno por impacto. Mostre risco, custo de não fazer, alternativa e efeito para operação ou usuário.', bridge: 'Essa visão amplia o olhar e aproxima o desenvolvedor do nível de percepção de um sênior.' },
  { id: 'mt-what-seniors-notice', slugPt: 'o-que-um-senior-observa-que-um-iniciante-ignora', slugEn: 'what-seniors-notice-that-beginners-ignore', title: { pt: 'O Que Um Sênior Observa Que Um Iniciante Ignora', en: 'What Seniors Notice That Beginners Ignore' }, excerpt: { pt: 'Sênior não enxerga apenas implementação. Ele observa consequência, risco, manutenção, comunicação e impacto no produto.', en: 'A senior does not see only implementation. They notice consequence, risk, maintenance, communication and product impact.' }, readTime: '15 min', tags: { pt: ['Sênior', 'Arquitetura', 'Carreira'], en: ['Senior', 'Architecture', 'Career'] }, keywords: { pt: ['desenvolvedor sênior', 'maturidade técnica', 'visão de produto'], en: ['senior developer', 'technical maturity', 'product vision'] }, subject: 'olhar sênior', angle: 'O iniciante pergunta como fazer. O sênior também pergunta se deveria fazer, qual custo terá e quem vai manter.', work: 'Isso aparece em estimativa, escolha de biblioteca, desenho de banco, fluxo de usuário e decisão de remover algo em vez de adicionar.', mistake: 'tratar senioridade como quantidade de tecnologias conhecidas', practice: 'Observe impacto antes da implementação e tente prever o segundo problema que nasce depois da primeira solução.', bridge: 'Arquitetura nasce exatamente desse tipo de olhar, sem precisar virar coleção de desenho bonito.' },
  { id: 'mt-learning-architecture-without-diagrams', slugPt: 'como-aprender-arquitetura-sem-virar-colecionador-de-diagramas', slugEn: 'how-to-learn-architecture-without-collecting-diagrams', title: { pt: 'Como Aprender Arquitetura Sem Virar Colecionador de Diagramas', en: 'How to Learn Architecture Without Becoming a Diagram Collector' }, excerpt: { pt: 'Arquitetura não é estética de caixas e setas. É decisão sobre responsabilidade, fluxo, acoplamento e evolução.', en: 'Architecture is not the aesthetics of boxes and arrows. It is decision making about responsibility, flow, coupling and evolution.' }, readTime: '16 min', tags: { pt: ['Arquitetura', 'Sistemas', 'Decisão Técnica'], en: ['Architecture', 'Systems', 'Technical Decision'] }, keywords: { pt: ['aprender arquitetura', 'arquitetura de software', 'diagramas'], en: ['learning architecture', 'software architecture', 'diagrams'] }, subject: 'aprendizado de arquitetura', angle: 'Diagramas ajudam quando explicam decisão. Quando viram decoração, escondem o que realmente importa.', work: 'Isso aparece quando a equipe desenha várias camadas, mas ninguém sabe dizer por que elas existem ou qual problema resolvem.', mistake: 'achar que arquitetura é aplicar padrão famoso', practice: 'Estude decisões reais, entenda tradeoffs, compare alternativas e desenhe apenas o suficiente para comunicar o raciocínio.', bridge: 'Em sistemas distribuídos, essa disciplina deixa de ser diferencial e vira sobrevivência.' },
  { id: 'mt-distributed-systems-discipline', slugPt: 'por-que-sistemas-distribuidos-cobram-disciplina', slugEn: 'why-distributed-systems-demand-discipline', title: { pt: 'Por Que Sistemas Distribuídos Cobram Disciplina', en: 'Why Distributed Systems Demand Discipline' }, excerpt: { pt: 'Quando o sistema se espalha em serviços, filas e redes, falhas deixam de ser exceção e passam a fazer parte do desenho.', en: 'When the system spreads into services, queues and networks, failures stop being exceptions and become part of the design.' }, readTime: '17 min', tags: { pt: ['Sistemas Distribuídos', 'Arquitetura', 'Infraestrutura'], en: ['Distributed Systems', 'Architecture', 'Infrastructure'] }, keywords: { pt: ['sistemas distribuídos', 'resiliência', 'arquitetura'], en: ['distributed systems', 'resilience', 'architecture'] }, subject: 'sistemas distribuídos', angle: 'Separar sistema em partes pode melhorar escala e organização, mas também cria rede, latência, falha parcial e consistência como problemas diários.', work: 'Isso aparece quando um serviço responde e outro não, uma fila atrasa ou duas partes discordam sobre o estado de uma operação.', mistake: 'distribuir antes de entender o monólito e os limites do domínio', practice: 'Pense em timeout, retry, idempotência, observabilidade, contrato e degradação aceitável antes de espalhar responsabilidade.', bridge: 'Para operar esse tipo de sistema, observabilidade precisa nascer junto com o primeiro deploy.' },
  { id: 'mt-observability-first-deploy', slugPt: 'como-pensar-em-observabilidade-desde-o-primeiro-deploy', slugEn: 'how-to-think-about-observability-from-first-deploy', title: { pt: 'Como Pensar em Observabilidade Desde o Primeiro Deploy', en: 'How to Think About Observability From the First Deploy' }, excerpt: { pt: 'Observabilidade não é luxo de sistema grande. É a capacidade de entender o que acontece quando ninguém está olhando o terminal.', en: 'Observability is not a luxury for large systems. It is the ability to understand what happens when nobody is watching the terminal.' }, readTime: '15 min', tags: { pt: ['Observabilidade', 'Logs', 'Monitoramento'], en: ['Observability', 'Logs', 'Monitoring'] }, keywords: { pt: ['observabilidade', 'monitoramento', 'logs'], en: ['observability', 'monitoring', 'logs'] }, subject: 'observabilidade desde cedo', angle: 'Se você só descobre problema quando usuário reclama, o sistema está operando no escuro.', work: 'Isso aparece em deploy silencioso, erro sem contexto, lentidão intermitente e comportamento que não reproduz localmente.', mistake: 'adicionar monitoramento apenas depois do incidente', practice: 'Defina logs úteis, métricas simples, alertas com ação clara e uma forma de rastrear operações críticas.', bridge: 'Quando o produto cresce, escolher o que monitorar passa a ser uma decisão de negócio e não apenas técnica.' },
  { id: 'mt-what-to-monitor-in-growing-product', slugPt: 'o-que-monitorar-em-produto-que-esta-crescendo', slugEn: 'what-to-monitor-in-a-growing-product', title: { pt: 'O Que Monitorar Em Um Produto Que Está Crescendo', en: 'What to Monitor in a Growing Product' }, excerpt: { pt: 'Monitorar tudo gera ruído. O importante é acompanhar sinais que mostram saúde, experiência, custo e risco operacional.', en: 'Monitoring everything creates noise. What matters is tracking signals that show health, experience, cost and operational risk.' }, readTime: '15 min', tags: { pt: ['Monitoramento', 'Produto', 'Operação'], en: ['Monitoring', 'Product', 'Operations'] }, keywords: { pt: ['monitoramento de produto', 'métricas técnicas', 'operação'], en: ['product monitoring', 'technical metrics', 'operations'] }, subject: 'métricas de operação', angle: 'Métrica boa ajuda alguém a agir. Se ninguém sabe o que fazer quando ela muda, talvez ela seja só decoração no painel.', work: 'Isso aparece em taxa de erro, tempo de resposta, fila acumulada, custo de infraestrutura, conversão e uso de recurso crítico.', mistake: 'encher dashboard para parecer controle', practice: 'Escolha poucos sinais com dono claro, limite saudável e ação esperada. Monitoramento precisa reduzir incerteza.', bridge: 'Mesmo com bons sinais, incidentes acontecem. A diferença está em como você responde sem perder controle.' },
  { id: 'mt-handling-incidents-calmly', slugPt: 'como-lidar-com-incidentes-sem-perder-controle', slugEn: 'how-to-handle-incidents-without-losing-control', title: { pt: 'Como Lidar Com Incidentes Sem Perder Controle', en: 'How to Handle Incidents Without Losing Control' }, excerpt: { pt: 'Incidente não é momento para ego. É momento para contenção, comunicação clara, investigação e aprendizado depois da estabilidade.', en: 'An incident is not a time for ego. It is a time for containment, clear communication, investigation and learning after stability.' }, readTime: '15 min', tags: { pt: ['Incidentes', 'Operação', 'Comunicação'], en: ['Incidents', 'Operations', 'Communication'] }, keywords: { pt: ['incidente em produção', 'postmortem', 'operação'], en: ['production incident', 'postmortem', 'operations'] }, subject: 'resposta a incidentes', angle: 'Sistema em produção vai falhar em algum momento. Maturidade aparece menos na ausência de falha e mais na forma de responder.', work: 'Isso aparece quando serviço cai, cobrança duplica, dado some, integração para ou usuário é afetado em escala.', mistake: 'procurar culpado enquanto o problema ainda está acontecendo', practice: 'Contenha impacto, comunique o necessário, registre linha do tempo, investigue causa e transforme aprendizado em ação concreta.', bridge: 'Muitos incidentes revelam dívida técnica, mas nem toda dívida técnica nasceu de erro.' },
  { id: 'mt-technical-debt-not-always-error', slugPt: 'por-que-divida-tecnica-nao-e-sempre-erro', slugEn: 'why-technical-debt-is-not-always-a-mistake', title: { pt: 'Por Que Dívida Técnica Não É Sempre Erro', en: 'Why Technical Debt Is Not Always a Mistake' }, excerpt: { pt: 'Dívida técnica pode ser escolha consciente. O problema é quando ninguém sabe que ela existe, por que foi aceita e quando será paga.', en: 'Technical debt can be a conscious choice. The problem is when nobody knows it exists, why it was accepted and when it will be paid.' }, readTime: '14 min', tags: { pt: ['Dívida Técnica', 'Arquitetura', 'Produto'], en: ['Technical Debt', 'Architecture', 'Product'] }, keywords: { pt: ['dívida técnica', 'refatoração', 'decisão técnica'], en: ['technical debt', 'refactoring', 'technical decision'] }, subject: 'dívida técnica consciente', angle: 'Dívida técnica não é palavrão. Às vezes é a forma racional de entregar valor agora e ajustar depois.', work: 'Isso aparece quando uma solução simples atende uma fase inicial, mas precisa ser revista se o produto crescer.', mistake: 'deixar dívida invisível até ela virar crise', practice: 'Registre motivo, impacto, prazo de revisão e sinais de que a dívida ficou cara demais.', bridge: 'A pergunta seguinte é quando refatorar, porque mexer cedo demais também pode desperdiçar energia.' },
  { id: 'mt-when-to-refactor', slugPt: 'como-decidir-quando-refatorar', slugEn: 'how-to-decide-when-to-refactor', title: { pt: 'Como Decidir Quando Refatorar', en: 'How to Decide When to Refactor' }, excerpt: { pt: 'Refatorar por incômodo estético nem sempre vale. Refatoração boa reduz risco, acelera mudança ou elimina custo recorrente.', en: 'Refactoring out of aesthetic discomfort is not always worth it. Good refactoring reduces risk, speeds change or removes recurring cost.' }, readTime: '14 min', tags: { pt: ['Refatoração', 'Código', 'Manutenção'], en: ['Refactoring', 'Code', 'Maintenance'] }, keywords: { pt: ['quando refatorar', 'refatoração', 'manutenção'], en: ['when to refactor', 'refactoring', 'maintenance'] }, subject: 'decisão de refatoração', angle: 'Refatoração não deveria ser fuga de tarefa difícil. Ela precisa ter motivo claro e benefício proporcional ao risco.', work: 'Isso aparece quando toda mudança em uma área quebra outra, quando duplicação causa divergência ou quando regra importante ficou impossível de entender.', mistake: 'refatorar tudo porque o código não está do jeito que você faria hoje', practice: 'Refatore perto da mudança real, proteja com teste, preserve comportamento e explique o ganho esperado.', bridge: 'Essa disciplina é uma das coisas que open source ensina de forma muito prática.' },
  { id: 'mt-open-source-real-work', slugPt: 'o-que-open-source-ensina-sobre-trabalho-real', slugEn: 'what-open-source-teaches-about-real-work', title: { pt: 'O Que Open Source Ensina Sobre Trabalho Real', en: 'What Open Source Teaches About Real Work' }, excerpt: { pt: 'Open source ensina comunicação escrita, revisão, paciência, leitura de contexto e respeito por código que outras pessoas mantêm.', en: 'Open source teaches written communication, review, patience, context reading and respect for code maintained by other people.' }, readTime: '14 min', tags: { pt: ['Open Source', 'Comunidade', 'Carreira'], en: ['Open Source', 'Community', 'Career'] }, keywords: { pt: ['open source', 'contribuição', 'carreira dev'], en: ['open source', 'contribution', 'dev career'] }, subject: 'contribuição open source', angle: 'Contribuir para open source não é só mandar código. É entrar em uma conversa que já existe e respeitar o trabalho de quem mantém o projeto.', work: 'Isso aparece em issue bem descrita, PR pequeno, revisão pública e decisão que precisa considerar usuários que você nem conhece.', mistake: 'chegar querendo reescrever tudo antes de entender o projeto', practice: 'Comece lendo contribuição, reproduza problema, corrija algo pequeno e comunique com clareza. Confiança vem por consistência.', bridge: 'Comunidades funcionam de forma parecida. Participar bem é diferente de só pedir ajuda.' },
  { id: 'mt-communities-without-only-asking', slugPt: 'como-participar-de-comunidades-sem-so-pedir-ajuda', slugEn: 'how-to-join-communities-without-only-asking-for-help', title: { pt: 'Como Participar de Comunidades Sem Só Pedir Ajuda', en: 'How to Join Communities Without Only Asking for Help' }, excerpt: { pt: 'Comunidade boa é troca. Quem só aparece para pedir resposta perde a chance de construir relação e aprender com mais profundidade.', en: 'A good community is exchange. People who only show up to ask for answers lose the chance to build relationships and learn deeper.' }, readTime: '13 min', tags: { pt: ['Comunidades', 'Discord', 'Networking'], en: ['Communities', 'Discord', 'Networking'] }, keywords: { pt: ['comunidade dev', 'discord', 'pedir ajuda'], en: ['dev community', 'discord', 'asking for help'] }, subject: 'participação em comunidades', angle: 'Comunidade não é suporte gratuito infinito. É ambiente de troca, e troca exige presença, respeito e contribuição.', work: 'Isso aparece em Discord, fórum, grupo de estudo, evento e qualquer espaço onde pessoas compartilham tempo e conhecimento.', mistake: 'chegar com urgência própria sem contexto e sem esforço demonstrado', practice: 'Mostre o que tentou, descreva erro, agradeça, compartilhe solução depois e ajude quando souber responder.', bridge: 'Discord pode ser um ambiente sério de aprendizado quando existe cultura e intenção.' },
  { id: 'mt-discord-as-serious-learning-space', slugPt: 'por-que-discord-pode-ser-ambiente-de-aprendizado-serio', slugEn: 'why-discord-can-be-a-serious-learning-space', title: { pt: 'Por Que Discord Pode Ser Ambiente de Aprendizado Sério', en: 'Why Discord Can Be a Serious Learning Space' }, excerpt: { pt: 'Discord não precisa ser bagunça. Com canais claros, moderação e cultura, ele vira espaço de estudo, troca e evolução técnica.', en: 'Discord does not need to be messy. With clear channels, moderation and culture, it becomes a space for study, exchange and technical growth.' }, readTime: '14 min', tags: { pt: ['Discord', 'Comunidades', 'Educação'], en: ['Discord', 'Communities', 'Education'] }, keywords: { pt: ['discord educação', 'comunidade de estudo', 'aprendizado'], en: ['discord education', 'study community', 'learning'] }, subject: 'Discord como ambiente de estudo', angle: 'A ferramenta não define a qualidade da comunidade. O que define é cultura, regra clara e gente disposta a manter o ambiente útil.', work: 'Isso aparece em canais de dúvida, estudos em grupo, feedback de projeto, eventos ao vivo e discussões técnicas organizadas.', mistake: 'achar que servidor movimentado é automaticamente servidor bom', practice: 'Crie canais com função clara, incentive contexto nas dúvidas, preserve histórico útil e reconheça contribuições boas.', bridge: 'Comunidade também pode ser origem de produtos digitais pequenos, que ensinam muito sobre construção real.' },
  { id: 'mt-small-digital-products', slugPt: 'como-criar-produtos-digitais-pequenos-que-ensinam-muito', slugEn: 'how-to-build-small-digital-products-that-teach-a-lot', title: { pt: 'Como Criar Produtos Digitais Pequenos Que Ensinam Muito', en: 'How to Build Small Digital Products That Teach a Lot' }, excerpt: { pt: 'Produtos pequenos obrigam você a pensar em problema, entrega, usuário, suporte e melhoria contínua sem depender de estrutura enorme.', en: 'Small products force you to think about problem, delivery, user, support and continuous improvement without a huge structure.' }, readTime: '14 min', tags: { pt: ['Produtos Digitais', 'Empreendedorismo', 'Software'], en: ['Digital Products', 'Entrepreneurship', 'Software'] }, keywords: { pt: ['produto digital', 'micro saas', 'projeto próprio'], en: ['digital product', 'micro saas', 'side project'] }, subject: 'produto digital pequeno', angle: 'Produto pequeno é laboratório sério. Ele mostra rapidamente se você sabe sair do código e pensar no uso real.', work: 'Isso aparece em ferramenta interna, bot, template, painel simples, checklist interativo ou automação vendida para um nicho específico.', mistake: 'tentar começar grande demais antes de validar utilidade', practice: 'Escolha uma dor pequena, entregue rápido, acompanhe uso e melhore com base em comportamento real.', bridge: 'Quando esse produto ganha recorrência, a conversa começa a se aproximar de SaaS.' },
  { id: 'mt-simple-saas-that-does-not-break', slugPt: 'o-que-um-saas-simples-precisa-ter-para-nao-quebrar', slugEn: 'what-a-simple-saas-needs-not-to-break', title: { pt: 'O Que Um SaaS Simples Precisa Ter Para Não Quebrar', en: 'What a Simple SaaS Needs to Avoid Breaking' }, excerpt: { pt: 'Mesmo SaaS pequeno precisa de autenticação, cobrança, suporte, logs, backup e caminho claro para resolver problema de usuário.', en: 'Even a small SaaS needs authentication, billing, support, logs, backup and a clear path to solve user problems.' }, readTime: '16 min', tags: { pt: ['SaaS', 'Produto', 'Arquitetura'], en: ['SaaS', 'Product', 'Architecture'] }, keywords: { pt: ['saas simples', 'micro saas', 'produto recorrente'], en: ['simple saas', 'micro saas', 'recurring product'] }, subject: 'SaaS pequeno', angle: 'SaaS não é apenas aplicação com login. É compromisso contínuo. Se alguém paga todo mês, espera estabilidade, suporte e evolução.', work: 'Isso aparece em cobrança falhando, senha esquecida, dado perdido, plano errado ou usuário precisando de resposta rápida.', mistake: 'pensar só na feature principal e esquecer operação', practice: 'Prepare autenticação, logs, backup, suporte, termos, cobrança e painel mínimo para entender saúde do produto.', bridge: 'Construir produto exige pensamento de negócio, sem abandonar a qualidade técnica.' },
  { id: 'mt-thinking-business-as-dev', slugPt: 'como-pensar-como-pessoa-de-negocio-sem-deixar-de-ser-dev', slugEn: 'how-to-think-like-business-without-stopping-being-dev', title: { pt: 'Como Pensar Como Pessoa de Negócio Sem Deixar de Ser Dev', en: 'How to Think Like Business Without Stopping Being a Developer' }, excerpt: { pt: 'Entender negócio não diminui profundidade técnica. Ajuda você a escolher melhor o que construir, quando construir e por quê.', en: 'Understanding business does not reduce technical depth. It helps you choose better what to build, when to build and why.' }, readTime: '15 min', tags: { pt: ['Negócios', 'Produto', 'Carreira'], en: ['Business', 'Product', 'Career'] }, keywords: { pt: ['dev e negócios', 'visão de produto', 'estratégia'], en: ['developer business', 'product vision', 'strategy'] }, subject: 'visão de negócio', angle: 'Desenvolvedor que entende negócio não vira menos técnico. Ele passa a aplicar técnica onde ela gera mais resultado.', work: 'Isso aparece quando precisa priorizar, cortar escopo, escolher arquitetura proporcional ou explicar custo de uma decisão.', mistake: 'achar que negócio é assunto de outra área', practice: 'Pergunte qual métrica muda, qual risco reduz, quem usa, quanto custa manter e que decisão o sistema precisa apoiar.', bridge: 'Essa visão também influencia crescimento financeiro, porque valor percebido depende de posicionamento.' },
  { id: 'mt-financial-growth-and-positioning', slugPt: 'por-que-crescimento-financeiro-tambem-depende-de-posicionamento', slugEn: 'why-financial-growth-also-depends-on-positioning', title: { pt: 'Por Que Crescimento Financeiro Também Depende de Posicionamento', en: 'Why Financial Growth Also Depends on Positioning' }, excerpt: { pt: 'Ganhar mais não depende apenas de saber mais. Depende de resolver problemas mais valiosos e comunicar esse valor com clareza.', en: 'Earning more does not depend only on knowing more. It depends on solving more valuable problems and communicating that value clearly.' }, readTime: '14 min', tags: { pt: ['Crescimento Financeiro', 'Carreira', 'Posicionamento'], en: ['Financial Growth', 'Career', 'Positioning'] }, keywords: { pt: ['crescimento financeiro dev', 'posicionamento', 'salário'], en: ['developer financial growth', 'positioning', 'salary'] }, subject: 'crescimento financeiro', angle: 'A remuneração cresce quando o mercado entende o valor que você entrega e quando esse valor resolve problemas relevantes.', work: 'Isso aparece em negociação salarial, proposta PJ, consultoria, produto próprio e mudança de nível profissional.', mistake: 'esperar reconhecimento sem deixar claro o impacto do trabalho', practice: 'Documente resultados, melhore comunicação, escolha problemas mais importantes e aprenda a negociar com base em evidência.', bridge: 'O último artigo fecha a expansão mostrando como continuar evoluindo depois que o básico já ficou para trás.' },
  { id: 'mt-keep-growing-after-basics', slugPt: 'como-continuar-evoluindo-quando-voce-ja-passou-do-basico', slugEn: 'how-to-keep-growing-after-you-pass-the-basics', title: { pt: 'Como Continuar Evoluindo Quando Você Já Passou do Básico', en: 'How to Keep Growing After You Have Passed the Basics' }, excerpt: { pt: 'Depois do básico, evolução depende de profundidade, responsabilidade, leitura de cenário e exposição a problemas mais difíceis.', en: 'After the basics, growth depends on depth, responsibility, context reading and exposure to harder problems.' }, readTime: '15 min', tags: { pt: ['Evolução', 'Carreira', 'Engenharia de Software'], en: ['Growth', 'Career', 'Software Engineering'] }, keywords: { pt: ['evoluir como desenvolvedor', 'além do básico', 'carreira dev'], en: ['growing as developer', 'beyond basics', 'dev career'] }, subject: 'evolução contínua', angle: 'Passar do básico é bom, mas também perigoso. É nesse momento que muita gente para de aprender com intenção e começa a repetir o que já sabe.', work: 'Isso aparece quando as tarefas ficam confortáveis demais, as mesmas soluções aparecem em todo projeto e o desconforto técnico desaparece.', mistake: 'confundir experiência acumulada com evolução real', practice: 'Busque problemas mais difíceis, leia código melhor que o seu, participe de decisões e revise periodicamente o que você evita estudar.', bridge: 'A trilha continua servindo como biblioteca para voltar, reler e conectar temas conforme a carreira muda de fase.' },
];

const getDateIndex = (index: number) => Math.min(Math.floor(index / 8), ptDates.length - 1);

const makeArticle = (topic: ExpansionTopic, index: number): MarketTrailArticle => {
  const dateIndex = getDateIndex(index);
  const isoDay = String(20 + dateIndex).padStart(2, '0');

  return {
    id: topic.id,
    slugPt: topic.slugPt,
    slugEn: topic.slugEn,
    title: topic.title,
    excerpt: topic.excerpt,
    date: { pt: ptDates[dateIndex], en: enDates[dateIndex] },
    publishedDate: `2026-02-${isoDay}`,
    readTime: topic.readTime,
    tags: topic.tags,
    keywords: topic.keywords,
    sections: [
      {
        title: { pt: 'O ponto que muita gente percebe tarde', en: 'What many people notice too late' },
        content: {
          pt: `${topic.angle}\n\nQuando o assunto é ${topic.subject}, evolução começa quando você para de procurar apenas a resposta pronta e passa a entender o motivo da decisão. No trabalho real quase nada chega perfeitamente organizado. Chega com prazo, contexto incompleto, limite técnico e consequência para outras pessoas.`,
          en: `${topic.excerpt.en}\n\nThe point is not to collect answers. The point is to understand why a decision makes sense, where it can fail and what consequence it creates for the people who depend on the software.`,
        },
      },
      {
        title: { pt: 'Onde isso aparece no trabalho real', en: 'Where this appears in real work' },
        content: {
          pt: `${topic.work}\n\nÉ nesse momento que o tema deixa de ser conteúdo salvo para depois e vira competência profissional. Quem trabalha com software precisa lidar com ambiguidade, explicar escolhas e manter qualidade mesmo quando o cenário não ajuda.`,
          en: `This shows up in real projects when deadlines, legacy systems, users, business rules and incomplete information meet in the same task.\n\nA developer grows when they can act with judgment in that environment instead of waiting for perfect conditions.`,
        },
      },
      {
        title: { pt: 'O erro que atrasa a evolução', en: 'The mistake that slows growth' },
        content: {
          pt: `O erro comum é ${topic.mistake}. Esse erro costuma parecer pequeno no começo, mas cria dependência, fragilidade e uma falsa sensação de avanço.\n\nA carreira em tecnologia cobra menos improviso do que parece. O que sustenta crescimento é critério repetido muitas vezes, em tarefas pequenas, decisões difíceis e conversas que exigem clareza.`,
          en: `The common mistake is treating the subject as something secondary until it becomes expensive.\n\nGood developers reduce that cost by noticing patterns earlier, asking better questions and turning vague problems into decisions that can be explained.`,
        },
      },
      {
        title: { pt: 'Como praticar com mais critério', en: 'How to practice with better judgment' },
        content: {
          pt: `${topic.practice}\n\nNão precisa transformar isso em um processo pesado. O objetivo é criar uma pequena mudança de comportamento que você consiga repetir. Consistência prática ensina mais do que uma semana intensa seguida de abandono.`,
          en: `Practice should be small enough to repeat and clear enough to evaluate.\n\nThe goal is not to create a heavy ritual. The goal is to make one better decision, observe the result and keep improving the way you work.`,
        },
      },
      {
        title: { pt: 'Para continuar lendo', en: 'Where to keep reading' },
        content: {
          pt: `${topic.bridge}\n\nEssa é a lógica desta trilha. Cada artigo resolve uma dúvida específica, mas também abre espaço para a próxima camada. Programação, carreira e mercado não evoluem separados. Eles se cruzam o tempo todo quando o trabalho deixa de ser exercício e vira responsabilidade.`,
          en: `This trail is built to connect technical skill, career growth and professional judgment.\n\nEach article answers one question, but also opens the next layer of the work. Software is not only code. It is responsibility, context and continuous decision making.`,
        },
      },
    ],
  };
};

export const careerGrowthExpansionArticles: MarketTrailArticle[] = topics.map(makeArticle);
export const careerGrowthExpansionArticleIds = careerGrowthExpansionArticles.map((article) => article.id);
